class MainActivity : AppCompatActivity() {
    private lateinit var api:ApiClient; private lateinit var root:LinearLayout; private var selectedCase:Int?=null; private var paidAccess:Boolean?=null; private val talkHistory=StringBuilder(); private val maxTalkContextChars=12000; private val maxSavedLegalWorkChars=100000
    private val pickEvidence=registerForActivityResult(ActivityResultContracts.OpenDocument()) { uri ->
        uri ?: return@registerForActivityResult
        val id=selectedCase ?: return@registerForActivityResult toast("Open a case first")
        busy("Uploading evidence…") { api.upload(id,uri); runOnUiThread { toast("Evidence uploaded and integrity hash created"); showCase(id) } }
    }
    override fun onCreate(savedInstanceState:Bundle?){ super.onCreate(savedInstanceState); api=ApiClient(this); if(api.token==null) showAuth() else showHome() }
    private val blue = Color.rgb(40,169,255)
    private val navy = Color.rgb(4,18,31)
    private val card = Color.rgb(11,35,54)
    private fun dp(v:Int)=(v*resources.displayMetrics.density).toInt()
    private fun base(){
        val signedIn=api.token!=null
        val shell=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setBackgroundColor(navy)}
        root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(14),dp(18),dp(14),dp(24));setBackgroundColor(navy)}
        if(signedIn) root.addView(appHeader())
        val scroll=ScrollView(this).apply{setBackgroundColor(navy);addView(root)}
        shell.addView(scroll,LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT,0,1f))
        if(signedIn) shell.addView(bottomNav())
        setContentView(shell)
    }
    private fun appHeader():View {
        val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=android.view.Gravity.CENTER_VERTICAL;setPadding(0,0,0,dp(12))}
        val justice=ImageButton(this).apply{
            setImageResource(R.drawable.ic_lady_justice);contentDescription="Open navigation menu";setBackgroundColor(Color.TRANSPARENT);scaleType=ImageView.ScaleType.CENTER_INSIDE;setPadding(0,0,0,0);setOnClickListener{showAppMenu()}
        }
        row.addView(justice,LinearLayout.LayoutParams(dp(52),dp(52)))
        val brand=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(8),0,0,0)}
        brand.addView(label("GA.LAW.HELP",21f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,0,0,0)})
        brand.addView(label("KNOW YOUR RIGHTS. PROTECT YOUR FUTURE.",9f).apply{setTextColor(blue);setPadding(0,0,0,0)})
        row.addView(brand,LinearLayout.LayoutParams(0,LinearLayout.LayoutParams.WRAP_CONTENT,1f))
        val account=TextView(this).apply{text="●";textSize=25f;setTextColor(Color.WHITE);gravity=android.view.Gravity.CENTER;contentDescription="Open profile";setOnClickListener{showProfile()}}
        row.addView(account,LinearLayout.LayoutParams(dp(44),dp(44)))
        return row
    }
    private fun navItem(icon:String,title:String,action:()->Unit)=TextView(this).apply{
        text="$icon\n$title";textSize=10f;setTextColor(Color.WHITE);gravity=android.view.Gravity.CENTER;setPadding(dp(3),dp(7),dp(3),dp(7));setOnClickListener{action()}
    }
    private fun bottomNav():View {
        val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;setPadding(dp(4),dp(3),dp(4),dp(5));background=GradientDrawable().apply{setColor(Color.rgb(7,28,44));setStroke(dp(1),Color.rgb(25,69,98))}}
        listOf(
            navItem("⌂","Home"){showHome()},
            navItem("⚖","Laws"){requirePaid{showLawSearch()}},
            navItem("💬","AI Help"){requirePaid{showTalkToMe()}},
            navItem("📁","Documents"){requirePaid{showDocuments()}},
            navItem("●","Account"){showProfile()}
        ).forEach{row.addView(it,LinearLayout.LayoutParams(0,LinearLayout.LayoutParams.WRAP_CONTENT,1f))}
        return row
    }
    private fun label(s:String,z:Float=16f)=TextView(this).apply{text=s;textSize=z;setTextColor(Color.WHITE);setPadding(0,8,0,8)}
    private fun field(h:String,pass:Boolean=false)=EditText(this).apply{hint=h;setHintTextColor(Color.rgb(155,174,190));setTextColor(Color.WHITE);setPadding(28,20,28,20);background=GradientDrawable().apply{cornerRadius=44f;setColor(Color.rgb(12,39,59));setStroke(2,blue)};if(pass) inputType=129}
    private fun button(s:String, f:()->Unit)=Button(this).apply{text=s;isAllCaps=false;setTextColor(Color.WHITE);textSize=15f;background=GradientDrawable().apply{cornerRadius=28f;setColor(card);setStroke(1,Color.rgb(29,67,94))};setOnClickListener{f()}}
    private fun homeCard(title:String,subtitle:String,action:()->Unit)=LinearLayout(this).apply{
        orientation=LinearLayout.VERTICAL;setPadding(24,22,24,22);background=GradientDrawable().apply{cornerRadius=28f;setColor(card);setStroke(1,Color.rgb(28,64,89))}
        addView(label(title,18f).apply{setTypeface(typeface,Typeface.BOLD)});addView(label(subtitle,13f).apply{setTextColor(Color.rgb(174,193,207))});setOnClickListener{action()}
    }
    private fun addHomeRow(vararg views:View){val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};views.forEach{row.addView(it,LinearLayout.LayoutParams(0,LinearLayout.LayoutParams.WRAP_CONTENT,1f).apply{setMargins(5,6,5,6)})};root.addView(row)}
    private fun homeSectionTitle(s:String)=label(s,12f).apply{setTextColor(blue);setTypeface(typeface,Typeface.BOLD);setPadding(0,20,0,6)}

    private fun showAuth(){ base();root.addView(label("STANDALONE ASSISTANT",14f));root.addView(label("GA.LAW.HELP",30f));val e=field("Email");val p=field("Password (15+ characters)",true);root.addView(e);root.addView(p);root.addView(button("Log in"){busy("Signing in…"){api.auth("/auth/login",e.text.toString(),p.text.toString());paidAccess=null;runOnUiThread{showHome()}}});root.addView(button("Create account"){busy("Creating account…"){val result=api.auth("/auth/register",e.text.toString(),p.text.toString());paidAccess=null;runOnUiThread{if(result.optBoolean("verification_required")) showVerification(e.text.toString()) else showHome()}}});root.addView(button("Browse Funny & Weird Laws free"){showFreeHome()});root.addView(button("Verify email"){showVerification(e.text.toString())});root.addView(button("Forgot password"){showPasswordReset(e.text.toString())}) }
    private fun showVerification(email:String){base();root.addView(label("VERIFY EMAIL",26f));root.addView(label("Open the verification email sent to $email. You can also paste its token below."));val t=field("Verification token");root.addView(t);root.addView(button("Verify"){busy("Verifying…"){api.verifyEmail(t.text.toString());runOnUiThread{toast("Email verified. Log in now.");showAuth()}}});root.addView(button("Resend email"){busy("Sending…"){api.resendVerification(email);runOnUiThread{toast("If the account exists, a new email was sent.")}}});root.addView(button("Back"){showAuth()})}
    private fun showPasswordReset(email:String){base();root.addView(label("RESET PASSWORD",26f));val e=field("Email").apply{setText(email)};val token=field("Reset token");val password=field("New password (15+ characters)",true);root.addView(e);root.addView(button("Send reset email"){busy("Sending…"){api.forgotPassword(e.text.toString());runOnUiThread{toast("If the account exists, a reset email was sent.")}}});root.addView(token);root.addView(password);root.addView(button("Set new password"){busy("Resetting…"){api.resetPassword(token.text.toString(),password.text.toString());runOnUiThread{toast("Password changed. Log in now.");showAuth()}}});root.addView(button("Back"){showAuth()})}
    private fun showHome(){selectedCase=null;base()
        root.addView(label("KNOW YOUR RIGHTS. PROTECT YOUR FUTURE.",12f).apply{setTextColor(blue);setPadding(0,0,0,22)})
        root.addView(label("GEORGIA LAWS. REAL HELP. REAL PEOPLE.",12f).apply{setTextColor(Color.rgb(148,166,180))})
        root.addView(label("LEGAL ANSWERS\nANYTIME.",31f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,5,0,5)})
        root.addView(label("Understand your rights. Get guidance. Stay informed. Be prepared.",14f).apply{setTextColor(Color.rgb(190,205,215));setPadding(0,0,0,18)})
        val ask=field("Ask GA.LAW.HELP anything...");root.addView(ask);root.addView(button("➜ Ask GA.LAW.HELP"){val q=ask.text.toString().trim();if(q.isNotEmpty())requirePaid{busy("Asking GA.LAW.HELP…"){val result=api.publicAsk(q);runOnUiThread{showAnswer("GA.LAW.HELP",result.optString("answer",result.toString()))}}}})
        addHomeRow(button("🎙 Voice Help"){requirePaid{showGuide("VOICE HELP","Use this screen to prepare what you want to ask. During a police encounter, stay calm, do not physically resist, and follow lawful safety instructions.")}},button("▣ Upload a Document"){requirePaid{showDocumentIntake()}},button("▣ Scan / Take Photo"){requirePaid{showDocumentIntake(true)}})
        root.addView(homeSectionTitle("RIGHTS & POLICE ENCOUNTERS"))
        addHomeRow(homeCard("🛡 Know\nMy Rights","Simple answers\nfor real situations"){requirePaid{showGuide("KNOW MY RIGHTS","Choose the situation you are dealing with and review plain-language legal information before deciding what to do.")}},homeCard("🚙 Traffic Stop","What to do and\nwhat to say"){requirePaid{showGuide("TRAFFIC STOP","Stay calm. Keep your hands visible. Avoid sudden movements. You can ask whether you are free to leave and clearly state that you do not consent to a search. Do not physically resist.")}},homeCard("♟ Questioned\nby Police","Stay calm.\nKnow your rights."){requirePaid{showGuide("QUESTIONED BY POLICE","You can clearly say that you wish to remain silent and want a lawyer. Do not lie, threaten, obstruct, or physically resist.")}})
        addHomeRow(homeCard("⛓ Arrested /\nDetained","Step-by-step help"){requirePaid{showGuide("ARRESTED / DETAINED","Stay calm and do not physically resist. Ask whether you are free to leave. If you are being questioned while in custody, clearly request a lawyer and state that you wish to remain silent.")}},homeCard("⚖ Georgia Laws","Search laws,\npenalties & more"){requirePaid{showLawSearch()}},homeCard("▤ Funny & Weird\nGeorgia Laws","Learn something\nnew"){showFunnyLaws()})
        root.addView(homeSectionTitle("YOUR LEGAL WORK"))
        addHomeRow(homeCard("💬 Ask\nGA.LAW.HELP","Get legal guidance\nwith AI"){requirePaid{showTalkToMe()}},homeCard("📁 My Documents","Store and manage\nyour files"){requirePaid{showDocuments()}},homeCard("▥ My Recordings","Your audio, saved\nsecurely"){requirePaid{showRecordings()}})
        root.addView(homeCard("⚖ "+tr("motions"),"Motions, appeals, sentencing and other legal work"){requirePaid{showLegalWorkHub()}},LinearLayout.LayoutParams(-1,-2).apply{setMargins(5,6,5,6)})
        root.addView(button("⚠  EMERGENCY INFORMATION\nImportant contacts and immediate steps"){showEmergencyInfo()},LinearLayout.LayoutParams(-1,-2).apply{setMargins(0,16,0,10)})
        root.addView(label("“Knowledge is power, especially when you need it most.”",15f).apply{gravity=android.view.Gravity.CENTER;setTextColor(Color.rgb(157,176,190));setTypeface(typeface,Typeface.ITALIC);setPadding(0,20,0,10)})
        root.addView(label("—  GA.LAW.HELP  —",12f).apply{gravity=android.view.Gravity.CENTER;setTextColor(blue)})
        root.addView(button("🗣 "+tr("talk")){requirePaid{showTalkToMe()}});root.addView(button("⚙ Settings"){showSettings()});root.addView(button("● Profile"){showProfile()});root.addView(button("$ Payment & Subscription"){showMembership()})
    }
    private fun showFreeHome(){base();root.addView(label("GA.LAW.HELP",30f).apply{setTypeface(typeface,Typeface.BOLD)});root.addView(label("FREE ACCESS",13f).apply{setTextColor(blue)});root.addView(label("Explore Georgia legal myths without creating an account. Every other app feature requires an active membership.",15f).apply{setPadding(0,18,0,18)});root.addView(homeCard("▤ Funny & Weird Georgia Laws","Separate internet folklore from verified law"){showFunnyLaws()});root.addView(button("Log in / create account"){showAuth()});root.addView(button("Emergency information"){toast("For immediate danger, contact emergency services.")})}
    private fun showFunnyLaws(){base();root.addView(button(if(api.token==null)"← Free home" else "← Home"){if(api.token==null)showFreeHome() else showHome()});root.addView(label("FUNNY & WEIRD GEORGIA LAWS",26f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,8)});root.addView(label("MYTH CHECKER — FREE",13f).apply{setTextColor(blue)});root.addView(label("Many viral “weird law” lists repeat local publicity stories or unsourced claims as if they were current statewide crimes. Treat the claims below as folklore until an official, current source verifies them.",15f).apply{setPadding(0,14,0,18)});arrayOf(
        "Fried chicken must be eaten by hand" to "Commonly tied to Gainesville local lore. It should not be presented as a current statewide Georgia criminal statute.",
        "A donkey may not be kept in a bathtub" to "A widely copied internet claim. GA.LAW.HELP does not label it current Georgia law without an official source.",
        "An ice-cream cone cannot be carried in a back pocket on Sunday" to "Another repeated web claim. Do not rely on it as current statewide law without checking the Georgia Code and local ordinances."
    ).forEach{(claim,check)->root.addView(homeCard("Claim: “$claim”",check){toast("Myth check: verify current official law before relying on this claim.")},LinearLayout.LayoutParams(-1,-2).apply{setMargins(0,7,0,7)})};root.addView(label("Legal-information note: old laws can be amended, repealed, preempted, or limited to a city or county. The official text and effective date control.",13f).apply{setTextColor(Color.rgb(174,193,207));setPadding(0,18,0,8)});root.addView(button("Open official Georgia Code"){openUrl("https://www.legis.ga.gov/legislation/georgia-code")});root.addView(button("Open Georgia court self-help resources"){openUrl("https://georgiacourts.gov/a2j/self-help-resources-highlighted-by-a2j/")})}
    private fun openUrl(url:String){if(!url.startsWith("https://"))return;runCatching{startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(url)))}.onFailure{toast("No browser is available.")}}
    private fun requirePaid(action:()->Unit){if(api.token==null){toast("Sign in and activate a membership to use this feature.");showAuth();return};if(paidAccess==true){action();return};busy("Checking membership…"){val status=api.billingStatus();paidAccess=status.optBoolean("paid");runOnUiThread{if(paidAccess==true)action() else showMembership(status)}}}
    private fun showMembership(status:JSONObject?=null){if(api.token==null){showAuth();return};if(status==null){base();root.addView(label("ACCOUNT / MEMBERSHIP",26f));busy("Checking membership…"){val fresh=api.billingStatus();paidAccess=fresh.optBoolean("paid");runOnUiThread{showMembership(fresh)}};return};base();root.addView(button("← Home"){showHome()});root.addView(label("ACCOUNT / MEMBERSHIP",26f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,10)});val active=status.optBoolean("paid");paidAccess=active;if(active){root.addView(label("✓ Active membership",18f).apply{setTextColor(blue)});root.addView(label("All paid GA.LAW.HELP features are unlocked on this account.",14f))}else{root.addView(label("Membership required",20f));root.addView(label("Funny & Weird Georgia Laws remains free. AI legal help, Georgia-law search, case work, documents, recordings, and legal-work tools require an active membership.",14f).apply{setTextColor(Color.rgb(190,205,215))});if(status.optBoolean("checkout_configured"))root.addView(button("Start secure checkout"){busy("Opening secure checkout…"){val result=api.createCheckout();val url=result.optString("checkout_url");runOnUiThread{if(url.startsWith("https://checkout.stripe.com/"))openUrl(url) else toast("Checkout is unavailable.")}}})else root.addView(label("Checkout is not available yet. Please try again later.",14f).apply{setTextColor(Color.rgb(255,190,120))});root.addView(button("Refresh membership"){paidAccess=null;showMembership()});root.addView(button("Browse the free myth checker"){showFunnyLaws()})};root.addView(button("Log out"){api.logout();paidAccess=null;showAuth()})}

    private fun languageCode():String { val saved=getSharedPreferences("ga_settings",MODE_PRIVATE).getString("language","English")?:"English"; return when { saved.startsWith("Español")->"es"; saved.startsWith("中文")->"zh"; saved.startsWith("Français")->"fr"; saved.startsWith("العربية")->"ar"; saved.startsWith("Tiếng Việt")->"vi"; else->"en" } }
    private fun tr(key:String):String { val id=resources.getIdentifier(when(key){"talk"->"talk_to_me";"settings"->"settings_language";"send"->"send";"language"->"language";"motions"->"motions_legal_work";"back"->"back_home";else->"home"},"string",packageName);return if(id!=0)getString(id) else key }
    private fun legalLanguageInstruction():String = when(languageCode()){"es"->"Respond in Spanish unless quoting an authority that should remain in its original language.";"zh"->"Respond in Simplified Chinese unless quoting an authority that should remain in its original language.";"fr"->"Respond in French unless quoting an authority that should remain in its original language.";"ar"->"Respond in Arabic unless quoting an authority that should remain in its original language.";"vi"->"Respond in Vietnamese unless quoting an authority that should remain in its original language.";else->"Respond in English."}
    private fun showTalkToMe(){base();root.addView(button(tr("back")){showHome()});root.addView(label("TALK TO ME",27f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,8)});root.addView(label("Have a back-and-forth conversation about Georgia law, rights, police encounters, cases, motions, sentencing, incarceration, appeals, or verified programs.",14f).apply{setTextColor(Color.rgb(174,193,207))});val history=talkHistory;val q=field("What do you want to talk about?");val conversation=label(history.toString(),15f);root.addView(conversation);root.addView(q);root.addView(button(tr("send")){val message=q.text.toString().trim();if(message.isNotEmpty()){val context=history.takeLast(maxTalkContextChars);val prompt="Continue a focused GA.LAW.HELP legal-information conversation. "+legalLanguageInstruction()+" Stay within Georgia law, rights, police encounters, criminal/civil legal procedure, motions, sentencing, incarceration/post-conviction issues, appeals, and verified legal programs. Do not answer unrelated general-chat questions. Conversation so far (recent context only):\n"+context+"\nUser: "+message;busy("Thinking…"){val answer=api.publicAsk(prompt).optString("answer");history.append("User: ").append(message).append("\nGA.LAW.HELP: ").append(answer).append("\n\n");runOnUiThread{conversation.text=history.toString();q.setText("")}}}});root.addView(button("New private conversation"){if(talkHistory.isEmpty())showTalkToMe() else AlertDialog.Builder(this).setTitle("Start a new private conversation?").setMessage("The current Talk to Me conversation is only in this app session unless you saved it to a case. Starting over will clear the unsaved conversation from this session.").setPositiveButton("Start new"){_,_->talkHistory.clear();showTalkToMe()}.setNegativeButton("Keep conversation",null).show()});root.addView(label("This conversation is kept only in this app session unless you explicitly save it to a case.",13f).apply{setTextColor(Color.rgb(148,166,180))});root.addView(button("Save / continue this work in a case"){if(history.isEmpty())toast("Start a legal conversation first.") else if(history.length>maxSavedLegalWorkChars) AlertDialog.Builder(this).setTitle("Conversation is too large to save safely").setMessage("This private conversation is larger than one saved legal-research item. Start a new private conversation before adding more work, or save an earlier portion first. Nothing has been deleted or silently shortened.").setPositiveButton("OK",null).show() else showTalkSaveCase(history.toString())})}
    private fun showTalkSaveCase(conversation:String){base();root.addView(button("← Talk to Me"){showTalkToMe()});root.addView(label("SAVE LEGAL WORK",25f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,8)});root.addView(label("Choose an existing case or create a new one. Nothing is saved unless you choose a case.",14f).apply{setTextColor(Color.rgb(174,193,207))});root.addView(button("＋ Create a new case"){newCase(conversation)});busy("Loading your cases…"){val cases=api.cases();runOnUiThread{if(cases.length()==0)root.addView(label("No saved cases yet. You can keep researching without saving, or create one when you are ready.",14f));for(i in 0 until cases.length()){val x=cases.optJSONObject(i)?:continue;val id=x.optInt("id");root.addView(button("Save to "+x.optString("title","Case #$id")){busy("Saving legal work…"){api.saveCaseNote(id,"Talk to Me legal research",conversation,languageCode());runOnUiThread{selectedCase=id;toast("Saved privately to this case.");showCase(id)}}})}}}}
    private fun showLanguageSettings(){base();root.addView(button("← Home"){showHome()});root.addView(label(tr("language"),27f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,8)});root.addView(label("Choose the app language. Full interface translation will be rolled out through this setting.",14f));arrayOf("English","Español (Spanish)","中文 (Chinese)","Français (French)","العربية (Arabic)","Tiếng Việt (Vietnamese)").forEach{language->root.addView(button(language){getSharedPreferences("ga_settings",MODE_PRIVATE).edit().putString("language",language).apply();val tag=when{language.startsWith("Español")->"es";language.startsWith("中文")->"zh-CN";language.startsWith("Français")->"fr";language.startsWith("العربية")->"ar";language.startsWith("Tiếng Việt")->"vi";else->"en"};AppCompatDelegate.setApplicationLocales(LocaleListCompat.forLanguageTags(tag));toast("Language preference saved: $language.")})}}
    private fun showLegalWorkHub(){base();root.addView(button("← Home"){showHome()});root.addView(label("MOTIONS & LEGAL WORK",27f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,8)});root.addView(label("Research first. Saving a case is optional.",14f).apply{setTextColor(Color.rgb(174,193,207))});root.addView(button("I am NOT incarcerated"){showLegalWorkPath("PENDING / COMMUNITY CASE","Research potentially relevant pretrial, evidence, discovery, bond, probation, sentencing, and other Georgia procedures. GA.LAW.HELP should verify the case stage, facts, deadlines, and legal authority before suggesting a motion.")});root.addView(button("I am incarcerated"){showLegalWorkPath("INCARCERATED / POST-CONVICTION","Research potentially relevant appellate, post-conviction, sentence, habeas, records/evidence, and verified program issues. Availability and deadlines depend on the judgment, procedural history, custody status, and current law.")});root.addView(button("Research without saving a case"){showGuide("LEGAL RESEARCH","Ask questions and investigate possible procedures without creating a saved case. If something becomes useful, you can later save the research to a case and build a draft for review.")})}
    private fun showLegalWorkPath(title:String,body:String){base();root.addView(button("← Motions & Legal Work"){showLegalWorkHub()});root.addView(label(title,24f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,10)});root.addView(label(body,15f));root.addView(label("A motion draft must identify its purpose, legal authority, required facts, timing/deadlines, supporting evidence, likely counterarguments, and uncertainties. Drafts are for review and are not automatically filed.",14f).apply{setTextColor(Color.rgb(174,193,207));setPadding(0,18,0,10)});root.addView(button("Ask GA.LAW.HELP about my situation"){showTalkToMe()});root.addView(button("Save / work inside a case"){showDocuments()})}
    private fun showDocumentIntake(imagesOnly:Boolean=false){base();root.addView(button("← Home"){showHome()});root.addView(label(if(imagesOnly) "SCAN / TAKE PHOTO" else "UPLOAD A DOCUMENT",27f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,8)});root.addView(label("Choose the case this belongs to. Your upload will be stored in that case's evidence workspace with its integrity hash.",14f).apply{setTextColor(Color.rgb(174,193,207))});root.addView(button("＋ Create a new case"){newCase()});busy("Loading your cases…"){val cases=api.cases();runOnUiThread{if(cases.length()==0)root.addView(label("No case exists yet. Create one first so the file has a secure case workspace.",15f));for(i in 0 until cases.length()){val x=cases.optJSONObject(i)?:continue;val id=x.optInt("id");root.addView(button("Add to "+x.optString("title","Case #$id")){selectedCase=id;pickEvidence.launch(if(imagesOnly) arrayOf("image/*") else arrayOf("*/*"))})}}}}
    private fun showRecordings(){base();root.addView(button("← Home"){showHome()});root.addView(label("MY RECORDINGS",27f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,8)});root.addView(label("Law-enforcement and legal-situation recordings",15f).apply{setTextColor(Color.rgb(174,193,207))});root.addView(label("Recording is intentionally not activated yet. Before microphone capture is enabled, GA.LAW.HELP will show a clear recording indicator, explain storage and deletion controls, and require the user to confirm that recording is lawful in their situation.",15f).apply{setPadding(0,20,0,12)});root.addView(label("Planned retention: user-controlled, with the requested 180–400 day range available as an option. The app will not silently start recording.",14f).apply{setTextColor(Color.rgb(174,193,207))});root.addView(button("Recording privacy & controls"){showGuide("RECORDING PRIVACY","Recordings are intended only for law-enforcement interactions or legal situations. Microphone access will require explicit permission and a visible active-recording state. Users will have deletion and retention controls before this feature is released.")})}
    private fun showDocuments(){base();root.addView(button("← Home"){showHome()});root.addView(label("MY DOCUMENTS",27f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,8)});root.addView(label("Your case files and uploaded evidence",14f).apply{setTextColor(Color.rgb(174,193,207))});root.addView(button("＋ Create Case"){newCase()});busy("Loading your cases…"){val cases=api.cases();runOnUiThread{if(cases.length()==0)root.addView(label("No case files yet. Create a case to securely organize documents and evidence.",15f));for(i in 0 until cases.length()){val x=cases.optJSONObject(i)?:continue;val id=x.optInt("id");root.addView(button("📁 "+x.optString("title","Case #$id")){showCase(id)})}}}}
    private fun showAnswer(title:String,body:String){base();root.addView(button("← Home"){showHome()});root.addView(label(title,27f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,14)});root.addView(label(body,16f).apply{setTextColor(Color.rgb(205,218,227))})}
    private fun showLawSearch(){base();root.addView(button("← Home"){showHome()});root.addView(label("GEORGIA LAWS",27f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,12)});val q=field("Search Georgia laws…");root.addView(q);root.addView(button("Search"){val s=q.text.toString().trim();if(s.isNotEmpty())busy("Searching Georgia law…"){val arr=api.searchAuthorities(s);val out=StringBuilder();for(i in 0 until arr.length()){val x=arr.optJSONObject(i)?:continue;out.append(x.optString("citation",x.optString("title","Georgia authority"))).append("\n").append(x.optString("title")).append("\n\n")};runOnUiThread{showAnswer("SEARCH RESULTS",if(out.isEmpty()) "No indexed authority matched that search." else out.toString())}}})}
    private fun showGuide(title:String,body:String){base();root.addView(button("← Home"){showHome()});root.addView(label(title,27f).apply{setTypeface(typeface,Typeface.BOLD);setPadding(0,28,0,14)});root.addView(label(body,16f).apply{setTextColor(Color.rgb(205,218,227))});root.addView(label("Important: GA.LAW.HELP provides legal information and does not create an attorney-client relationship.",13f).apply{setTextColor(Color.rgb(148,166,180));setPadding(0,24,0,8)})}
    private fun newCase(pendingLegalWork:String?=null){val box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(30,0,30,0)};val t=field("Case title");val c=field("Georgia county/circuit");val s=field("Stage (pretrial, appeal, habeas…)");val n=field("Tell us what happened");listOf(t,c,s,n).forEach{box.addView(it)};AlertDialog.Builder(this).setTitle("New case").setView(box).setPositiveButton("Create"){_,_->val title=t.text.toString().trim();val narrative=n.text.toString();when{title.isEmpty()->toast("Enter a case title.");title.length>255->toast("Case title must be 255 characters or fewer.");c.text.toString().length>100->toast("County/circuit must be 100 characters or fewer.");s.text.toString().length>80->toast("Case stage must be 80 characters or fewer.");narrative.length>100000->toast("Case details must be 100,000 characters or fewer.");else->busy("Creating case…"){val o=api.createCase(title,c.text.toString().trim(),s.text.toString().trim(),narrative);val id=o.getInt("id");if(!pendingLegalWork.isNullOrBlank())api.saveCaseNote(id,"Talk to Me legal research",pendingLegalWork,languageCode());runOnUiThread{if(!pendingLegalWork.isNullOrBlank())toast("Case created and legal research saved privately.");showCase(id)}}}}.setNegativeButton("Cancel",null).show()}
    private fun showCase(id:Int){selectedCase=id;base();root.addView(button("← My Cases"){showHome()});root.addView(label("CASE WORKSPACE",26f));busy("Loading case…"){val c=api.caseDetail(id);val ev=api.evidence(id);val tl=api.timeline(id);runOnUiThread{root.addView(label(c.optString("title","Case #$id"),22f));root.addView(label("${c.optString("county","")} • ${c.optString("stage","")}",13f));root.addView(button("⚖ Analyze Case"){runAnalysis(id)});root.addView(button("📝 Saved Legal Research"){showCaseNotes(id)});root.addView(button("Why? — Sources & Authority"){showWhy(id)});root.addView(button("Red-Team My Case"){showRedTeam(id)});root.addView(button("Second-Look / Appeal Review"){showSecondLook(id)});root.addView(button("＋ Add evidence / video / document"){pickEvidence.launch(arrayOf("*/*"))});root.addView(label("EVIDENCE",14f));for(i in 0 until ev.length()){val o=ev.getJSONObject(i);root.addView(label("✓ ${o.optString("filename")}\nSHA-256: ${o.optString("sha256").take(20)}…",13f))};root.addView(label("MASTER TIMELINE",14f));for(i in 0 until tl.length()){val o=tl.getJSONObject(i);root.addView(label("${o.optString("title")} • ${o.optString("source_label")}",14f))}}}}
    private fun showCaseNotes(id:Int){base();root.addView(button("← Case"){showCase(id)});root.addView(label("SAVED LEGAL RESEARCH",25f));root.addView(label("Only items you explicitly saved to this case appear here.",13f).apply{setTextColor(Color.rgb(174,193,207))});busy("Loading saved legal work…"){val notes=api.caseNotes(id);runOnUiThread{if(notes.length()==0){root.addView(label("Nothing has been saved to this case yet.",14f));return@runOnUiThread};for(i in 0 until notes.length()){val n=notes.getJSONObject(i);val noteId=n.optLong("id");root.addView(label(n.optString("title","Saved legal research"),18f).apply{setTypeface(typeface,Typeface.BOLD)});root.addView(label(n.optString("content"),14f));root.addView(label("Language: "+n.optString("language","en")+" • "+n.optString("created_at",""),12f).apply{setTextColor(Color.rgb(148,166,180))});root.addView(button("Delete this saved item"){AlertDialog.Builder(this).setTitle("Delete saved legal research?").setMessage("This removes this saved item from the case. This cannot be undone.").setPositiveButton("Delete"){_,_->busy("Deleting…"){api.deleteCaseNote(id,noteId);runOnUiThread{toast("Saved item deleted.");showCaseNotes(id)}}}.setNegativeButton("Cancel",null).show()})}}}}
    private fun runAnalysis(id:Int)=busy("Screening case…"){val o=api.runAnalysis(id);runOnUiThread{showJsonFindings("CASE INTELLIGENCE",o,"findings")}}
    private fun showWhy(id:Int)=busy("Loading authority…"){val o=api.why(id);runOnUiThread{showJsonFindings("WHY? — VERIFIED AUTHORITY",o,"why")}}
    private fun showRedTeam(id:Int)=busy("Red-teaming…"){val o=api.redTeam(id);runOnUiThread{showJsonFindings("RED-TEAM",o,"items")}}
    private fun showSecondLook(id:Int)=busy("Running second-look…"){val o=api.secondLook(id);runOnUiThread{showJsonFindings("SECOND-LOOK",o,"screening")}}
    private fun showJsonFindings(title:String,o:JSONObject,key:String){base();root.addView(button("← Case"){selectedCase?.let{showCase(it)}});root.addView(label(title,24f));val a=o.optJSONArray(key);if(a==null||a.length()==0){root.addView(label("No verified results are attached yet. Add more case facts/records or link verified authority."));return};for(i in 0 until a.length()){val x=a.getJSONObject(i);val head=x.optString("issue",x.optString("proposition","Finding ${i+1}"));val body=x.optString("analysis",x.optString("citation",x.toString()));val counter=x.optString("counterargument","");root.addView(label(head,18f));root.addView(label(body,14f));if(counter.isNotBlank())root.addView(label("Counterargument: $counter",13f))}}
    private fun busy(msg:String,job:()->Unit){toast(msg);thread{try{job()}catch(e:Exception){runOnUiThread{toast(e.message?:"Request failed")}}}}
    private fun toast(s:String)=Toast.makeText(this,s,Toast.LENGTH_LONG).show()
}
